using System.Text;
using HotelManagementSystem.Application;
using HotelManagementSystem.Contracts;
using HotelManagementSystem.Infrastructure;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Diagnostics;
using Microsoft.IdentityModel.Tokens;
var builder=WebApplication.CreateBuilder(args);
builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();
var postgresConnection=builder.Configuration.GetConnectionString("Postgres");builder.Services.AddDbContext<HmsDbContext>(o=>{if(string.IsNullOrWhiteSpace(postgresConnection))o.UseSqlServer(builder.Configuration.GetConnectionString("SqlServer"));else o.UseNpgsql(postgresConnection);o.ConfigureWarnings(w=>w.Ignore(RelationalEventId.PendingModelChangesWarning));});
builder.Services.AddScoped(typeof(IRepository<>),typeof(Repository<>));builder.Services.AddScoped<AuthService>();builder.Services.AddScoped<ReservationService>();builder.Services.AddScoped<CarRentalService>();builder.Services.AddScoped<ExperienceBookingService>();builder.Services.AddScoped<HostChatService>();builder.Services.AddHttpClient();builder.Services.AddScoped<SmtpEmailSender>();builder.Services.AddScoped<BrevoEmailSender>();builder.Services.AddScoped<IEmailSender>(sp=>string.IsNullOrWhiteSpace(builder.Configuration["Brevo:ApiKey"])?sp.GetRequiredService<SmtpEmailSender>():sp.GetRequiredService<BrevoEmailSender>());
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new(){ValidateIssuer=true,ValidateAudience=true,ValidateLifetime=false,ValidateIssuerSigningKey=true,ValidIssuer=builder.Configuration["Jwt:Issuer"],ValidAudience=builder.Configuration["Jwt:Audience"],IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(builder.Configuration["Jwt:Key"]!))});builder.Services.AddAuthorization();
var app=builder.Build();using(var scope=app.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<HmsDbContext>();if(string.IsNullOrWhiteSpace(postgresConnection))await db.Database.MigrateAsync();else {await db.Database.EnsureCreatedAsync();await db.Database.ExecuteSqlRawAsync("CREATE TABLE IF NOT EXISTS \"Cars\" (\"Id\" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, \"City\" text NOT NULL, \"Brand\" text NOT NULL, \"Model\" text NOT NULL, \"Year\" integer NOT NULL, \"Category\" text NOT NULL, \"DailyPrice\" numeric(18,2) NOT NULL, \"Seats\" integer NOT NULL, \"Luggage\" integer NOT NULL, \"Transmission\" text NOT NULL, \"Fuel\" text NOT NULL, \"AirConditioning\" boolean NOT NULL, \"UnlimitedKilometers\" boolean NOT NULL)");await db.Database.ExecuteSqlRawAsync("CREATE TABLE IF NOT EXISTS \"CarRentals\" (\"Id\" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, \"CarId\" integer NOT NULL REFERENCES \"Cars\"(\"Id\") ON DELETE CASCADE, \"GuestId\" integer NOT NULL REFERENCES \"Guests\"(\"Id\") ON DELETE CASCADE, \"PickupDate\" date NOT NULL, \"DropoffDate\" date NOT NULL, \"DrivingLicenseId\" text NOT NULL, \"PickupLocation\" text NOT NULL)");await db.Database.ExecuteSqlRawAsync("CREATE TABLE IF NOT EXISTS \"ExperienceBookings\" (\"Id\" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, \"GuestId\" integer NOT NULL REFERENCES \"Guests\"(\"Id\") ON DELETE CASCADE, \"City\" text NOT NULL, \"Title\" text NOT NULL, \"Category\" text NOT NULL, \"Address\" text NOT NULL, \"Date\" date NOT NULL, \"ArrivalTime\" time without time zone NOT NULL, \"Price\" numeric(18,2) NOT NULL, \"Participants\" integer NOT NULL)");await db.Database.ExecuteSqlRawAsync("CREATE TABLE IF NOT EXISTS \"HostMessages\" (\"Id\" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, \"ReservationId\" integer NOT NULL REFERENCES \"Reservations\"(\"Id\") ON DELETE CASCADE, \"GuestId\" integer NOT NULL REFERENCES \"Guests\"(\"Id\") ON DELETE CASCADE, \"Sender\" text NOT NULL, \"Body\" text NOT NULL, \"SentAtUtc\" timestamp with time zone NOT NULL)");}await DataSeeder.SeedAsync(db);await CatalogSeeder.SeedAsync(db);await AdminSeeder.SeedAsync(db,builder.Configuration);}app.UseMiddleware<ExceptionMiddleware>();app.UseDefaultFiles();app.UseStaticFiles();app.UseSwagger();app.UseSwaggerUI();app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.Run();
public class ExceptionMiddleware(RequestDelegate next){public async Task Invoke(HttpContext c){try{await next(c);}catch(DomainException e){c.Response.StatusCode=400;await c.Response.WriteAsJsonAsync(new ApiResponse<object>(false,null,e.Message));}catch(DbUpdateException){c.Response.StatusCode=409;await c.Response.WriteAsJsonAsync(new ApiResponse<object>(false,null,"A record with the same unique value already exists."));}catch(Exception){c.Response.StatusCode=500;await c.Response.WriteAsJsonAsync(new ApiResponse<object>(false,null,"An unexpected error occurred."));}}}
